import java.util.Arrays;
import java.util.List;
import java.util.ArrayList;

public class GenericMethodDemo {
    // Generic utility: converts an array of any reference type to an ArrayList
    public static <E> List<E> toArrayList(E[] array) {
        List<E> list = new ArrayList<>(array.length);
        for (E element : array) {
            list.add(element);
        }
        return list;
    }

    // Generic swap on any reference array
    public static <T> void swap(T[] a, int i, int j) {
        T temp = a[i];
        a[i] = a[j];
        a[j] = temp;
    }

    public static void main(String[] args) {
        String[] fruits = {"Apple", "Banana", "Cherry"};
        swap(fruits, 0, 2); // Inferred T = String
        System.out.println("After swap: " + Arrays.toString(fruits));

        Integer[] numbers = {10, 20, 30};
        List<Integer> numList = toArrayList(numbers); // Inferred E = Integer
        System.out.println("Converted to List: " + numList);

        // Explicit type witness invocation
        List<String> explicitList = GenericMethodDemo.<String>toArrayList(fruits);
        System.out.println("Explicit witness list: " + explicitList);
    }
}
// Expected Output:
// After swap: [Cherry, Banana, Apple]
// Converted to List: [10, 20, 30]
// Explicit witness list: [Cherry, Banana, Apple]

