practiceProblems.solutionCode:
import java.util.Objects;

public class ElementCounter {
    public static <T> int countOccurrences(T[] array, T target) {
        if (array == null) return 0;
        int count = 0;
        for (T item : array) {
            if (Objects.equals(item, target)) {
                count++;
            }
        }
        return count;
    }

    public static void main(String[] args) {
        String[] words = {"cat", "dog", "cat", "bird", "cat"};
        System.out.println(countOccurrences(words, "cat"));

        Integer[] nums = {1, 2, 3, 2, 2, 5};
        System.out.println(countOccurrences(nums, 2));
    }
}

