import java.util.List;
import java.util.ArrayList;

public class ListZipper {
    public static class Pair<A, B> {
        final A a;
        final B b;
        Pair(A a, B b) { this.a = a; this.b = b; }
        @Override public String toString() { return "(" + a + "," + b + ")"; }
    }

    public static <A, B> List<Pair<A, B>> zip(List<A> listA, List<B> listB) {
        List<Pair<A, B>> result = new ArrayList<>();
        if (listA == null || listB == null) return result;
        int limit = Math.min(listA.size(), listB.size());
        for (int i = 0; i < limit; i++) {
            result.add(new Pair<>(listA.get(i), listB.get(i)));
        }
        return result;
    }

    public static void main(String[] args) {
        List<String> names = List.of("Alice", "Bob", "Charlie");
        List<Integer> ages = List.of(25, 30);
        System.out.println(zip(names, ages));
    }
}

